// Simulasi pembacaan hasil scan Nmap (untuk latihan logika)
// Ubah nilai di bawah ini untuk mencoba skenario lain.

const ipTarget = '10.1.2.5';
const portFtp = 21;
const anonymousLoginAllowed = true; // coba ubah: false

console.log(`Target: ${ipTarget}`);
console.log(`Menguji port FTP: ${portFtp}/tcp`);

if (anonymousLoginAllowed) {
  console.log(`Port ${portFtp}/tcp terbuka. Anonymous login: tersedia. Lanjut ke FileZilla ✅`);
} else {
  console.log(`Port ${portFtp}/tcp terbuka. Anonymous login: tidak tersedia. Perlu kredensial lain ❌`);
}

// Simulasi workflow FTP: create directory lalu upload file

const server = {
  ip: '10.1.2.5',
  user: 'Anonymous',
  port: 21
};

const remoteDirectory = 'test';
const filesToUpload = ['foto.jpg', 'tugas.txt', 'laporan.pdf'];

console.log(`Koneksi FTP ke ${server.ip}:${server.port} sebagai ${server.user}...`);
console.log(`Membuat folder remote: ${remoteDirectory} ...`);

if (!remoteDirectory) {
  console.log('Gagal: nama folder tidak boleh kosong');
} else {
  console.log(`Folder ${remoteDirectory} dibuat ✅`);
  console.log('Mulai upload file:');
  filesToUpload.forEach((f, i) => {
    console.log(`  ${i + 1}. ${f} -> /${remoteDirectory}/${f}`);
  });
  console.log('Semua upload selesai ✅');
}
